"""Personal experiences only. Empty publication collections are deliberate, never seeded stories."""
from pathlib import Path
import html, json, re
ROOT=Path(__file__).resolve().parent.parent
DATA=json.loads((ROOT/'content/sony/experiences.json').read_text())
E=lambda value: html.escape(str(value),quote=True)
NAV=[('/sony/daily-devotion/','Daily Devotion'),('/sony/three-daily-wins/','The Three Daily Wins'),('/sony/blog/','Blog')]
def resource_hub():
    cards=''.join(f'<a class="resource-door door-{i}" href="{path}"><span class="exp-eyebrow">0{i+1} / PERSONAL</span><h3>{label}</h3><p>{text}</p><span class="door-arrow" aria-hidden="true">↗</span></a>' for i,((path,label),text) in enumerate(zip(NAV,['Make room for the Word. A quiet place to reflect.','Spirit. Body. Mind. Small practices, lived intentionally.','Essays and reflections. Read at your own pace.'])))
    return f'<section id="personal-resources" class="exp-hub frame" aria-labelledby="resources-title"><p class="exp-eyebrow">CONTINUE THE CONVERSATION</p><h2 id="resources-title">PERSONAL REFLECTIONS &amp; RESOURCES</h2><div class="resource-doors">{cards}</div></section><!-- end-personal-resources -->'
def wrap(page,title,description,body,path,kind):
    nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==path else '')+f'>{label}</a>' for p,label in NAV)
    content=f'<div class="experience experience-{kind}"><nav class="experience-nav frame" aria-label="Sony Alexis resources"><a class="experience-owner" href="/sony/">Sony Alexis <span>/ Personal</span></a><div>{nav}</div></nav>{body}<div class="experience-back frame"><a href="/sony/#personal-resources">← Personal reflections &amp; resources</a></div></div>'
    doc=page(title,description,content,path)
    doc=doc.replace('<link rel="stylesheet" href="/group.css">','<link rel="preload" href="/assets/inter-400.woff2" as="font" type="font/woff2" crossorigin="anonymous"><link rel="stylesheet" href="/group.css">')
    return doc.replace('</head>','<link rel="stylesheet" href="/sony/experiences.css"><script type="module" src="/sony/experiences.js"></script></head>')
def devotion():
    scripture=DATA['scripture']
    prompts=[('reflection','Reflection','Read slowly. What does the passage say? Notice its words before drawing a conclusion.'),('repent','REPENT','Where might you need to turn toward God? Take time for an honest response.'),('put-off','PUT OFF','Consider one attitude or habit you need to set aside. Keep your response specific.'),('put-on','PUT ON','Consider the faithful alternative. What would putting it into practice look like?'),('application','Application','Choose one small, concrete action you can take today.'),('prayer','Prayer','Bring your response to God in your own words. There is no required script here.')]
    accordions=''.join(f'<details class="reflection-detail"><summary><span class="exp-eyebrow">0{i+1}</span><span>{title}</span><span class="detail-plus" aria-hidden="true">+</span></summary><div class="detail-content"><p>{text}</p></div></details>' for i,(_,title,text) in enumerate(prompts))
    return f'''<header class="devotion-hero frame"><div><p class="exp-eyebrow">DAILY DEVOTION / A QUIETER RHYTHM</p><h1>Room for<br><em>the Word.</em></h1><p class="exp-intro">Slow down. Read attentively.<br>Carry something true into your day.</p></div><div class="devotion-orbit" aria-hidden="true"><span></span><i></i><b>BE STILL</b></div></header>
<section class="scripture-practice frame" aria-labelledby="scripture-title"><div class="section-rail"><p class="exp-eyebrow">01 / SCRIPTURE PRACTICE</p><p class="quiet-note">{E(scripture['note'])}</p></div><div class="scripture-panel"><p class="exp-eyebrow" id="scripture-title">{E(scripture['reference'])} · EXCERPT</p><div class="memory-stage"><blockquote id="memory-verse">“{E(scripture['excerpt'])}”</blockquote><p id="memory-cover" hidden>Pause. Recall the words.<br><em>Let them come back slowly.</em></p></div><p class="verse-attribution">{E(scripture['version'])}</p><div class="memory-actions"><button type="button" data-memory-toggle aria-controls="memory-verse" aria-expanded="true" disabled>Hide passage · practice recall</button><span id="memory-status" role="status">Read, pause, then recall.</span></div><noscript><p>The passage remains readable without JavaScript. Hide/reveal practice requires JavaScript.</p></noscript></div></section>
<section class="reflection-room frame" aria-labelledby="reflection-title"><div class="section-rail"><p class="exp-eyebrow">02 / PERSONAL RESPONSE</p><h2 id="reflection-title">Read. Reflect.<br><em>Respond.</em></h2><p>Optional prompts, not a published reflection by Sony Alexis. Your responses stay with you; nothing is submitted or saved.</p></div><div class="reflection-stack">{accordions}</div></section>
<section class="devotion-archive frame" aria-labelledby="devotion-archive-title"><div class="archive-heading"><div><p class="exp-eyebrow">THE DEVOTION ARCHIVE</p><h2 id="devotion-archive-title">A place to return.</h2></div><span class="archive-count">00 / PUBLISHED</span></div><div class="devotion-empty"><span class="empty-rule" aria-hidden="true"></span><h3>Space for what is still to come.</h3><p>No daily devotions have been published here yet. Approved entries will appear in this archive, with their Scripture, reflection, application and prayer.</p><p class="quiet-note">The Scripture practice above is available now. It is not an archive entry.</p></div></section>'''
def wins():
    pillars=[('spirit','SPIRITUAL WIN','Return to what matters.','Read a short Scripture passage slowly, then make a quiet moment for prayer.','An invitation to attention and reflection—not a test of faith.'),('body','PHYSICAL WIN','Care for the body you have.','Take a comfortable five-minute walk, or choose gentle seated movement that suits your ability.','Adapt to your circumstances. Stop if movement feels uncomfortable.'),('mind','INTELLECTUAL WIN','Leave room to learn.','Read a page of something worthwhile and note one useful idea.','Choose curiosity over volume. One considered idea is enough.')]
    cards=''.join(f'<article class="win-pillar pillar-{key}" data-pillar="{key}"><div class="pillar-top"><span class="exp-eyebrow">0{i+1} / {label}</span><span class="pillar-symbol" aria-hidden="true"><i></i></span></div><h2>{heading}</h2><p class="challenge-label">TODAY’S SUGGESTED PRACTICE</p><p class="win-challenge">{challenge}</p><p class="win-purpose">{purpose}</p><button type="button" data-win="{key}" aria-pressed="false" disabled><span class="completion-icon" aria-hidden="true">+</span><span class="completion-text">Mark complete</span></button><span class="pillar-state">Not marked complete</span></article>' for i,(key,label,heading,challenge,purpose) in enumerate(pillars))
    return f'''<header class="wins-hero frame"><p class="exp-eyebrow">SPIRIT. BODY. MIND.</p><h1>THE THREE<br><em>DAILY WINS</em></h1><p class="wins-statement">WIN THE DAY IN THREE WAYS.<br>EVERY SINGLE DAY.</p><div class="wins-hero-bottom"><p>Three small invitations to live with intention.<br>Not a measure of spiritual worth.</p><p class="day-label" data-local-day>YOUR LOCAL CALENDAR DAY</p></div></header><section class="daily-dashboard frame" aria-label="Daily personal-growth practices"><div class="dashboard-summary"><div class="progress-orbit"><svg viewBox="0 0 140 140" aria-hidden="true"><circle class="progress-track" cx="70" cy="70" r="56"/><circle class="progress-fill" cx="70" cy="70" r="56" pathLength="100"/></svg><output id="wins-count" aria-label="Practices marked complete">0<span>/3</span></output></div><div><p class="exp-eyebrow">YOUR DAY, AT YOUR PACE</p><h2 id="wins-progress-label">Begin with one.</h2><p id="wins-progress-note">0 of 3 practices marked complete. This is not a measure of spiritual worth.</p><p class="storage-note" role="status">Progress stays in this browser and resets with your local calendar day. Nothing is sent to a server.</p></div></div><div class="win-pillars">{cards}</div><div class="wins-complete" id="wins-complete" hidden tabindex="-1"><span class="exp-eyebrow">SPIRIT · BODY · MIND</span><h2>THREE WINS. ONE INTENTIONAL DAY. KEEP GROWING.</h2><p>Let this be encouragement, not a verdict on your value. You can change any completion above.</p></div><noscript><p class="experience-notice">JavaScript is off. The practices are readable, but local completion tracking is unavailable.</p></noscript></section>'''
def blog():
    categories=DATA['categories']
    filters='<button type="button" data-category="all" aria-pressed="true" disabled>All writing <span>00</span></button>'+''.join(f'<button type="button" data-category="{c["id"]}" aria-pressed="false" disabled>{E(c["name"])}</button>' for c in categories)
    rooms=''.join(f'<a href="?category={c["id"]}#writing" class="reading-room" data-room="{c["id"]}"><span class="exp-eyebrow">0{i+1} / READING ROOM</span><h3>{E(c["name"])}</h3><p>{E(c["description"])}</p><span class="room-count">NO PUBLISHED ARTICLES <b aria-hidden="true">↗</b></span></a>' for i,c in enumerate(categories))
    return f'''<header class="journal-masthead frame"><div class="masthead-top"><span class="exp-eyebrow">SONY ALEXIS / WRITING</span><span class="exp-eyebrow">FAITH. IDEAS. EVERYDAY LIFE.</span></div><h1>The <em>Journal.</em></h1><div class="masthead-bottom"><span>BLOG / ESSAYS &amp; REFLECTIONS</span><span>A little more room to think.</span></div></header><section class="journal-feature frame" aria-labelledby="journal-feature-title"><div class="feature-type"><span class="exp-eyebrow">THE NEXT PAGE</span><h2 id="journal-feature-title">Considered words.<br><em>Unhurried reading.</em></h2><p>Space for faith, growth, leadership and the texture of ordinary life.</p></div><div class="feature-empty"><span class="editorial-mark" aria-hidden="true">Aa</span><p>No articles have been published here yet.</p><span>When there is something to share, it belongs here.</span></div></section><section class="journal-writing frame" id="writing" aria-labelledby="writing-title"><div class="archive-heading"><h2 id="writing-title">The reading rooms.</h2><span class="archive-count">00 / PUBLISHED ARTICLES</span></div><nav class="journal-filters" aria-label="Article categories">{filters}</nav><p class="filter-status" role="status">No published articles. Explore a category below.</p><div class="reading-rooms">{rooms}</div><noscript><p>Category filtering needs JavaScript. All four categories remain visible below.</p></noscript></section>'''
def render_article(article, articles):
    """Future real approved records only; tests use synthetic records outside public output."""
    if article.get('published') is not True: raise ValueError('Only explicitly published article records may render')
    if not re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',article['slug']): raise ValueError('Invalid article slug')
    if article['category'] not in {c['id'] for c in DATA['categories']}: raise ValueError('Unknown article category')
    sections=''.join(f'<section id="article-section-{i}"><h2>{E(s["heading"])}</h2>'+''.join(f'<p>{E(p)}</p>' for p in s['paragraphs'])+'</section>' for i,s in enumerate(article['sections']))
    related=[a for a in articles if a.get('published') is True and re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',a['slug']) and a['slug']!=article['slug'] and a['category']==article['category']]
    links=''.join(f'<a class="related-article" href="/sony/blog/{E(a["slug"])}/">{E(a["title"])}</a>' for a in related)
    return f'<div class="reading-progress" aria-hidden="true"><span></span></div><article class="editorial-article frame"><header><p class="exp-eyebrow">SONY ALEXIS / JOURNAL</p><h1>{E(article["title"])}</h1></header><div class="article-prose">{sections}</div></article><section class="related-reading frame"><h2>Continue reading.</h2>{links or "<p>No related articles published yet.</p>"}</section>'
def build_experiences(page):
    if DATA['devotions'] or DATA['articles']:
        raise ValueError('Publication collections require an explicitly reviewed publishing connection.')
    entries=[('/sony/daily-devotion/','Daily Devotion','A quiet Scripture practice and space for future approved daily devotions.',devotion(),'devotion'),('/sony/blog/','Blog | Sony Alexis','A personal editorial journal: faith, growth, leadership and life. No articles published yet.',blog(),'journal')]
    for path,title,description,body,kind in entries:
        dest=ROOT/'public'/path.strip('/')/'index.html'
        dest.parent.mkdir(parents=True,exist_ok=True)
        dest.write_text(wrap(page,title,description,body,path,kind))
    from sony_book import build_book
    build_book(page)
    return [p for p,_ in NAV]
